import math

import math

def nth_magical_number(n, a, b):
    l = a * b // math.gcd(a, b)
    lo, hi = 1, n * min(a, b)
    while lo < hi:
        m = (lo + hi) // 2
        if m // a + m // b - m // l >= n:
            hi = m
        else:
            lo = m + 1
    return lo % (10**9 + 7)

