int nthMagicalNumber(int n, int a, int b) {
    long long l = (long long)a / __gcd(a, b) * b, lo = 1, hi = (long long)n * min(a, b);
    while (lo < hi) { long long m = (lo + hi) / 2; if (m / a + m / b - m / l >= n) hi = m; else lo = m + 1; }
    return lo % 1000000007;
}
